/// HTTP client for the Worker API (`rust/api/`). The only file that makes
/// network calls to our backend.
///
/// Every request carries the signed-in user's Firebase ID token; the Worker
/// verifies it and derives the uid from it. Never send a uid in a body.
///
/// Request bodies come from Rust (`lib/src/rust/api/*.dart`, generated by
/// flutter_rust_bridge) so validation and JSON shape match the Worker exactly.
///
/// For tests, override [apiClientProvider] with a fake — don't mock `http`.
library;

import 'dart:async';

import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:http/http.dart' as http;

import 'api_exception.dart';

class ApiClient {
  ApiClient({http.Client? httpClient, FirebaseAuth? auth, String? baseUrl})
      : _http = httpClient ?? http.Client(),
        _auth = auth ?? FirebaseAuth.instance,
        _baseUrl = baseUrl ?? dotenv.env['API_BASE_URL'] ?? '';

  final http.Client _http;
  final FirebaseAuth _auth;
  final String _baseUrl;

  static const _timeout = Duration(seconds: 15);

  /// POSTs [jsonBody] (an already-encoded JSON string) to [path].
  /// Returns the response body. Throws an [ApiException] on any failure.
  Future<String> postJson(String path, String jsonBody) async {
    final user = _auth.currentUser;
    if (user == null) throw ApiUnauthenticatedException(path);

    final http.Response response;
    try {
      final token = await user.getIdToken();
      response = await _http
          .post(
            Uri.parse('$_baseUrl$path'),
            headers: {
              'Authorization': 'Bearer $token',
              'Content-Type': 'application/json',
            },
            body: jsonBody,
          )
          .timeout(_timeout);
    } on Exception catch (e, st) {
      // Offline, DNS, TLS, timeout, token refresh failure.
      throw ApiNetworkException(path, e, st);
    }

    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw ApiResponseException(path, response.statusCode, response.body);
    }
    return response.body;
  }
}

final apiClientProvider = Provider<ApiClient>((ref) => ApiClient());
